
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const euro=new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR',maximumFractionDigits:0});
const fmt=n=>new Intl.NumberFormat('de-DE',{maximumFractionDigits:0}).format(Number(n)||0);
const pct=n=>`${(Number(n)||0).toFixed(1).replace('.',',')} %`;
const APP_VERSION='7.1-enterprise-foundation';
const SUPPLIER_SEED={"Chefs Culinar":"Lebensmittel","Hans Fäßler GmbH":"Fleisch","Team Beverage":"Getränke","Backhaus Lederer":"Bäckerei / Lebensmittel","Bunzl":"Reinigungsmittel / To-Go / Verpackung","Spalter":"Getränke","DBL":"Berufsbekleidung","ReFood":"Entsorgung","GVO Personal":"Fremdpersonal","Stüwer":"Automaten / Reparatur","Warenautomaten Triftshäuser":"Automaten / Reparatur","Zucchetti":"IT / Software","STS":"Geldverkehr","Deutsche Leasing":"Leasing","WISAG Dienstleistungsholding":"Interne Sachkosten","B&W":"Druck / Pauschale","Eli":"Sonstige","Interne Rechnung":"Intern / gemischt","Kostenerstattung":"Gemischt"};
const MONTH_NAMES=['Januar','Februar','März','April','Mai','Juni','Juli','August','September','Oktober','November','Dezember'];
const ROLE_DEFS={
  team:{label:'Team',views:['live'],actions:['live.write']},
  gl:{label:'Gastronomieleitung',views:['live','monat','hebel','analysen','betrieb'],actions:['live.write','upload','config.edit','backup','site.manage','site.switch']},
  regional:{label:'Regionalleitung',views:['live','monat','hebel','analysen','betrieb'],actions:['upload','backup','site.switch']},
  admin:{label:'Admin',views:['live','monat','hebel','analysen','betrieb'],actions:['*']}
};
const DEFAULT_SITE={id:'betrieb-1',name:'Betrieb 1',contract:'Kosten-plus',employees:0,seats:0};
const defaultState={active:'live',monthMode:'cockpit',selectedMonthKey:null,analysisPeriod:'12',analysisDetail:null,analysisPointKey:null,site:'Betrieb 1',theme:'dark',archives:[],live:{monthKey:null,entries:[]},liveGoals:{revenue:35000,meals:700,db1:2500,waste:70,ware:44},profile:{contract:'Kosten-plus',employees:0,seats:0},supplierMap:{...SUPPLIER_SEED},flosiq:{enabled:false,lastSync:null,mode:'same-origin'},workspace:{orgId:'local-org',orgName:'Meine Organisation',siteId:'betrieb-1',user:'Lokaler Nutzer',role:'gl',backend:'local'},sites:[DEFAULT_SITE],auditLog:[],integrations:{cloud:{status:'ready',provider:null,lastSync:null},wisag:{status:'ready',provider:null,lastSync:null}},benchmarks:{records:[],minCohort:5,siteToken:null},pilot:{startedAt:null,notes:[]}};
function currentSite(){return state.sites?.find(x=>x.id===state.workspace?.siteId)||state.sites?.[0]||DEFAULT_SITE}
function currentRole(){return ROLE_DEFS[state.workspace?.role]||ROLE_DEFS.gl}
function can(action){const a=currentRole().actions||[];return a.includes('*')||a.includes(action)}
function canView(view){return (currentRole().views||[]).includes(view)}
function addAudit(action,details='',level='info'){
  state.auditLog=Array.isArray(state.auditLog)?state.auditLog:[];
  state.auditLog.unshift({id:(globalThis.crypto?.randomUUID?.()||String(Date.now())+Math.random()),at:new Date().toISOString(),action,details:String(details||''),level,user:state.workspace?.user||'lokal',role:state.workspace?.role||'gl',siteId:state.workspace?.siteId||'default'});
  state.auditLog=state.auditLog.slice(0,500);
}
function siteIdOf(x){return x?.siteId||state?.workspace?.siteId||'betrieb-1'}
function safeId(text){return String(text||'betrieb').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,40)||'betrieb'}

let state=loadState(),chartRegistry={};
function clone(v){return JSON.parse(JSON.stringify(v))}
function loadState(){
  try{
    const rawV7=localStorage.getItem('metriq_state_v7'),rawV6=localStorage.getItem('metriq_state_v6'),saved=JSON.parse(rawV7||rawV6||'null');
    if(saved){
      const s={...clone(defaultState),...saved},legacyName=String(saved.site||'Betrieb 1'),legacyId=safeId(legacyName)||'betrieb-1';
      const legacySite={...DEFAULT_SITE,id:legacyId,name:legacyName,contract:saved.profile?.contract||DEFAULT_SITE.contract,employees:+saved.profile?.employees||0,seats:+saved.profile?.seats||0};
      s.sites=Array.isArray(saved.sites)&&saved.sites.length?saved.sites.map(x=>({...DEFAULT_SITE,...x})):[legacySite];
      s.workspace={...defaultState.workspace,...(saved.workspace||{})};
      if(!saved.workspace?.siteId)s.workspace.siteId=s.sites[0].id;
      if(!s.sites.some(x=>x.id===s.workspace.siteId))s.workspace.siteId=s.sites[0].id;
      if(!saved.workspace?.orgName)s.workspace.orgName='Meine Organisation';
      if(!saved.workspace?.user)s.workspace.user='Lokaler Nutzer';
      const cs=s.sites.find(x=>x.id===s.workspace.siteId)||s.sites[0];
      s.site=cs.name;s.profile={...defaultState.profile,...(saved.profile||{}),contract:cs.contract||saved.profile?.contract||defaultState.profile.contract,employees:cs.employees??saved.profile?.employees??0,seats:cs.seats??saved.profile?.seats??0};
      s.archives=Array.isArray(saved.archives)?saved.archives:[];
      s.archives=s.archives.map(a=>({...a,siteId:a.siteId||s.workspace.siteId,audit:{sheetCount:a.audit?.sheetCount||0,verified:a.audit?.verified||0,conflicts:a.audit?.conflicts||0,warnings:a.audit?.warnings||0,checks:a.audit?.checks||[],coverage:a.audit?.coverage||[],confidence:a.audit?.confidence??(a.audit?.conflicts?70:90),version:a.audit?.version||'legacy',...a.audit}}));
      s.live={...defaultState.live,...(saved.live||{})};
      s.live.entries=Array.isArray(saved.live?.entries)?saved.live.entries.map(e=>({...e,siteId:e.siteId||s.workspace.siteId})):[];
      s.liveGoals={...defaultState.liveGoals,...(saved.liveGoals||{})};
      s.supplierMap={...SUPPLIER_SEED,...(saved.supplierMap||{})};
      s.flosiq={...defaultState.flosiq,...(saved.flosiq||{})};
      s.auditLog=Array.isArray(saved.auditLog)?saved.auditLog:[];
      s.integrations={...defaultState.integrations,...(saved.integrations||{}),cloud:{...defaultState.integrations.cloud,...(saved.integrations?.cloud||{})},wisag:{...defaultState.integrations.wisag,...(saved.integrations?.wisag||{})}};
      s.benchmarks={...defaultState.benchmarks,...(saved.benchmarks||{})};
      s.pilot={...defaultState.pilot,...(saved.pilot||{})};
      s.theme=['dark','light'].includes(saved.theme)?saved.theme:'dark';
      const arr=s.archives.filter(a=>(a.siteId||s.workspace.siteId)===s.workspace.siteId).sort((a,b)=>a.key.localeCompare(b.key));
      if(!arr.some(a=>a.key===s.selectedMonthKey))s.selectedMonthKey=arr.at(-1)?.key||null;
      return s;
    }
    const old=JSON.parse(localStorage.getItem('metriq_state')||'null'),s=clone(defaultState);
    if(old?.site){s.site=old.site;s.sites[0].name=old.site;s.sites[0].id=safeId(old.site);s.workspace.siteId=s.sites[0].id}
    if(old?.live?.entries)s.live.entries=old.live.entries.map(e=>({...e,siteId:s.workspace.siteId}));
    if(old?.live?.monthKey)s.live.monthKey=old.live.monthKey;
    if(old?.liveGoals)s.liveGoals={...s.liveGoals,...old.liveGoals};
    if(old?.profile){s.profile={...s.profile,...old.profile};s.sites[0]={...s.sites[0],contract:s.profile.contract,employees:s.profile.employees,seats:s.profile.seats}}
    return s;
  }catch(e){console.warn(e);return clone(defaultState)}
}
function saveState(){localStorage.setItem('metriq_state_v7',JSON.stringify(state))}


function applyTheme(){
  document.body.dataset.theme=state.theme;
  document.documentElement.style.colorScheme=state.theme;
  const btn=$('#themeBtn');
  if(btn){btn.textContent=state.theme==='dark'?'☀️':'🌙';btn.title=state.theme==='dark'?'Light Mode':'Dark Mode'}
  const meta=document.querySelector('meta[name="theme-color"]');
  if(meta)meta.setAttribute('content',state.theme==='dark'?'#0b0814':'#f4f1f8');
}
function toggleTheme(){state.theme=state.theme==='dark'?'light':'dark';saveState();applyTheme();render();toast(state.theme==='dark'?'Dark Mode':'Light Mode')}

function readLSJson(key,fallback=[]){
  try{const x=JSON.parse(localStorage.getItem(key)||'null');return x??fallback}catch{return fallback}
}
function flosiqRaw(){
  const entries=readLSJson('nm_entries',[]);
  const meals=readLSJson('nm_meals',[]);
  const menus=readLSJson('nm_menus',[]);
  const rescues=readLSJson('flosiq_rescues_v1',[]);
  const decisions=readLSJson('flosiq_rescue_decisions_v1',[]);
  const available=Array.isArray(entries)&&entries.length||Array.isArray(meals)&&meals.length||localStorage.getItem('flosiq_management_theme')!==null;
  return {
    available:!!available,
    entries:Array.isArray(entries)?entries:[],
    meals:Array.isArray(meals)?meals:[],
    menus:Array.isArray(menus)?menus:[],
    rescues:Array.isArray(rescues)?rescues:[],
    decisions:Array.isArray(decisions)?decisions:[],
    costPerKg:+localStorage.getItem('flosiq_cost_per_kg')||0,
    prepCostPerKg:+localStorage.getItem('flosiq_prep_cost_per_kg')||0,
    storageCostPerKg:+localStorage.getItem('flosiq_storage_cost_per_kg')||0
  };
}
function flosiqMonthData(key){
  const raw=flosiqRaw(),es=raw.entries.filter(x=>String(x.date||'').startsWith(key)),ms=raw.meals.filter(x=>String(x.date||'').startsWith(key));
  const meals=ms.reduce((s,x)=>s+(+x.meals||0),0);
  const waste=es.reduce((s,x)=>s+(+x.weight_kg||0),0);
  const lunchEntries=es.filter(x=>x.service==='lunch');
  const lunchWaste=lunchEntries.reduce((s,x)=>s+(+x.weight_kg||0),0);
  const unknown=es.some(x=>x.service==='unassigned');
  const foodLoss=meals>0&&lunchEntries.length&&!unknown?lunchWaste*1000/meals:null;
  const cats={plate:0,prep:0,overproduction:0,storage:0};
  es.forEach(x=>{if(cats[x.category]!=null)cats[x.category]+=+x.weight_kg||0});
  const rescues=raw.rescues.filter(x=>String(x.date||x.createdAt||'').startsWith(key));
  const decisions=raw.decisions.filter(x=>String(x.date||'').startsWith(key));
  let estimatedValue=0,valuedKg=0;
  es.forEach(x=>{
    const kg=+x.weight_kg||0;let factor=0;
    if(x.category==='plate'||x.category==='overproduction')factor=raw.costPerKg;
    else if(x.category==='prep')factor=raw.prepCostPerKg;
    else if(x.category==='storage')factor=raw.storageCostPerKg;
    if(factor>0){estimatedValue+=kg*factor;valuedKg+=kg}
  });
  return {connected:state.flosiq.enabled&&raw.available,available:raw.available,meals,waste,lunchWaste,foodLoss,cats,rescues:rescues.length,decisions,estimatedValue,valuedKg,costPerKg:raw.costPerKg};
}
function connectFlosiq(){
  if(!can('config.edit'))return toast('Keine Berechtigung');
  const raw=flosiqRaw();
  if(!raw.available){
    openModal(`<h2>FLOSIQ noch nicht gefunden</h2><p class="help-copy">MetriQ sucht direkt nach den FLOSIQ-Daten im Browser. Das funktioniert automatisch, wenn beide Apps unter derselben Web-Adresse / demselben GitHub-Pages-Host laufen und FLOSIQ auf diesem Gerät bereits Daten gespeichert hat.</p><div class="notice"><div class="ico">↔</div><div><b>Kein Datenbestand gefunden.</b><p>Öffne FLOSIQ auf diesem Gerät, erfasse bzw. lade die Daten und komm danach hierher zurück.</p></div></div>`);
    return;
  }
  state.flosiq.enabled=true;state.flosiq.lastSync=new Date().toISOString();addAudit('integration.flosiq.connected','FLOSIQ Bridge lokal verbunden');saveState();closeModal();render();toast('FLOSIQ verbunden ✓');
}
function disconnectFlosiq(){if(!can('config.edit'))return toast('Keine Berechtigung');state.flosiq.enabled=false;addAudit('integration.flosiq.disconnected','FLOSIQ Bridge getrennt');saveState();render();toast('FLOSIQ getrennt')}
function conferenceRows(r){
  const rows=(r?.revenueBookings||[]).filter(x=>x.type==='Faktura HK'&&x.net>0);
  return rows.filter(x=>{
    const t=`${x.service||''} ${x.customer||''}`.toLowerCase();
    return !/abschlagsrechnung|budgetkontrolle|spitzabrechnung|nachzahlung|gesamt:/.test(t);
  });
}
function conferenceGroups(r){
  const map=new Map();
  for(const x of conferenceRows(r)){
    const code=String(x.costCenter||'').trim();
    const label=String(x.customer||'').trim()||code||String(x.service||'Konferenz').trim();
    const key=code||label;
    const cur=map.get(key)||{code,label,revenue:0,bookings:0,rows:[]};
    cur.revenue+=+x.net||0;cur.bookings++;cur.rows.push(x);map.set(key,cur);
  }
  return [...map.values()].sort((a,b)=>b.revenue-a.revenue);
}
function conferenceTotal(r){return conferenceGroups(r).reduce((s,x)=>s+x.revenue,0)}
function foreignPersonal(r){return (r?.parts||[]).reduce((s,p)=>s+(+p.personalForeign||0),0)}
function supplierGoodsTotal(r){return (r?.suppliers||[]).reduce((s,x)=>s+(+x.goods||0),0)}

function sortedArchives(){return [...state.archives].filter(a=>siteIdOf(a)===state.workspace.siteId).sort((a,b)=>a.key.localeCompare(b.key))}
function selectedRecord(){return state.archives.find(a=>a.key===state.selectedMonthKey)||sortedArchives().at(-1)||null}
function calc(r=selectedRecord()){if(!r)return{revenue:0,ware:0,personal:0,sach:0,totalCosts:0,db1:0,warePct:0,personalPct:0,sachPct:0,totalCostPct:0,db1Pct:0};const m=r.metrics||{},revenue=+m.revenue||0,ware=+m.ware||0,personal=+m.personal||0,sach=+m.sach||0,totalCosts=+m.totalCosts||ware+personal+sach,db1=Number.isFinite(+m.db1)?+m.db1:revenue-totalCosts;return{revenue,ware,personal,sach,totalCosts,db1,warePct:revenue?ware/revenue*100:0,personalPct:revenue?personal/revenue*100:0,sachPct:revenue?sach/revenue*100:0,totalCostPct:revenue?totalCosts/revenue*100:0,db1Pct:revenue?db1/revenue*100:0}}
function canonicalMonthKey(text){const s=String(text||''),y=(s.match(/20\d{2}/)||[])[0],mn=MONTH_NAMES.findIndex(m=>s.toLowerCase().includes(m.toLowerCase()));return y&&mn>=0?`${y}-${String(mn+1).padStart(2,'0')}`:null}
function monthLabel(key){if(!key)return'—';const[y,m]=key.split('-').map(Number);return`${MONTH_NAMES[m-1]} ${y}`}
function monthShort(key){if(!key)return'--/--';const[y,m]=key.split('-');return`${m}/${y.slice(-2)}`}
function liveMonthMeta(){const d=new Date(),key=state.live.monthKey||`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;state.live.monthKey=key;return{key,label:monthLabel(key),short:monthShort(key)}}
function infoButton(key){return`<button class="info-btn" data-info="${key}" aria-label="Erklärung">i</button>`}
function monthNavigator(){const arr=sortedArchives(),idx=arr.findIndex(a=>a.key===state.selectedMonthKey),r=selectedRecord();return`<div class="month-nav"><button data-month-step="-1" ${idx<=0?'disabled':''}>‹</button><button class="month-main" data-open-months><small>ANGEZEIGTER MONAT</small><strong>${r?.month||'Kein Abschluss'}</strong><em>${arr.length} ${arr.length===1?'Abschluss':'Abschlüsse'} gespeichert · antippen zum Wechseln</em></button><button data-month-step="1" ${idx<0||idx>=arr.length-1?'disabled':''}>›</button></div>`}
function monthTabs(){return`<div class="segment"><button data-month-mode="cockpit" class="${state.monthMode==='cockpit'?'active':''}">Monatscockpit</button><button data-month-mode="deep" class="${state.monthMode==='deep'?'active':''}">Deep Scan</button></div>`}
function render(){chartRegistry={};if(!canView(state.active))state.active='live';$$('.nav-item').forEach(b=>{b.hidden=!canView(b.dataset.nav);b.classList.toggle('active',b.dataset.nav===state.active)});const views={live:liveView,monat:monthView,hebel:hebelView,analysen:analysisView,betrieb:betriebView};$('#screenHost').innerHTML=(views[state.active]||liveView)();requestAnimationFrame(()=>{bindScreen();animateIn();bindCharts()})}
function stepMonth(dir){const arr=sortedArchives(),idx=arr.findIndex(a=>a.key===state.selectedMonthKey),next=arr[idx+Number(dir)];if(next){state.selectedMonthKey=next.key;state.analysisPointKey=next.key;saveState();render();scrollTo({top:0,behavior:'smooth'})}}
function liveTotals(){
  const key=liveMonthMeta().key,entries=(state.live.entries||[]).filter(e=>siteIdOf(e)===state.workspace.siteId&&e.date?.startsWith(key)),days=entries.length;
  const manualMeals=entries.reduce((a,e)=>a+(+e.meals||0),0),revenue=entries.reduce((a,e)=>a+(+e.revenue||0),0),goods=entries.reduce((a,e)=>a+(+e.goods||0),0);
  const f=flosiqMonthData(key),meals=f.connected&&f.meals>0?f.meals:manualMeals;
  const last=sortedArchives().at(-1),c=calc(last),opening=Math.max(1,last?.metrics?.openingDays||20),structural=Math.max(0,c.totalCosts-c.ware),liveDb1=revenue-goods-(structural/opening*days);
  return{entries,days,meals,revenue,goods,liveDb1,goodsRate:revenue?goods/revenue*100:0,flosiq:f}
}
function liveView(){
  const lm=liveMonthMeta(),l=liveTotals(),last=sortedArchives().at(-1),lc=calc(last),f=l.flosiq;
  return `<section class="screen"><div class="eyebrow">METRIQ LIVE · ${lm.short} · ${currentSite().name}</div><h1 class="title">Dein Monat entsteht gerade.</h1><p class="subtitle">Echte Ist-Daten für den laufenden Monat. ProphetIQ prognostiziert – MetriQ misst und verifiziert später mit dem Abschluss.</p>
    ${last?`<div class="live-summary"><div class="live-summary-top"><div><div class="eyebrow">LETZTE VERIFIZIERTE WAHRHEIT</div><h3>${last.month}</h3><p class="subtitle" style="font-size:11px">${last.audit.sheetCount} Tabellenblätter geprüft · ${last.audit.conflicts} Konflikte · ${last.audit.confidence??'—'}% Datenvertrauen</p></div><span class="chip good">✓ verifiziert</span></div><div class="live-mini"><div><small>Nettoerlös</small><b>${euro.format(lc.revenue)}</b></div><div><small>Wareneinsatz</small><b>${pct(lc.warePct)}</b></div><div><small>DB1</small><b>${pct(lc.db1Pct)}</b></div><div><small>Essen</small><b>${fmt(last.metrics.meals)}</b></div></div><button class="ghost" data-go-month="${last.key}" style="width:100%;margin-top:12px">Abschluss ansehen →</button></div>`:`<div class="notice"><div class="ico">◎</div><div style="flex:1"><b>Noch kein verifizierter Abschluss für ${currentSite().name}.</b><p>Lade den ersten Monatsabschluss hoch. Danach bildet MetriQ die belastbare Vergleichsbasis.</p>${can('upload')?'<button class="primary" data-start-upload style="margin-top:9px">Ersten Abschluss hochladen →</button>':''}</div></div>`}
    <div class="section-head"><div><div class="eyebrow">AKTUELLER MONAT</div><h2>${lm.label}</h2></div>${can('live.write')?'<button class="primary" data-open-daily>＋ Heute</button>':''}</div>
    <div class="kpi-grid"><article class="kpi"><div class="kpi-top"><span class="label">Erlös erfasst</span></div><div class="value">${euro.format(l.revenue)}</div><div class="delta">${l.days} MetriQ-Tage erfasst</div></article><article class="kpi"><div class="kpi-top"><span class="label">Essen</span></div><div class="value">${fmt(l.meals)}</div><div class="delta">${f.connected?'automatisch aus FLOSIQ':'manuell erfasst'}</div></article><article class="kpi"><div class="kpi-top"><span class="label">Warenzugang</span>${infoButton('warenzugang')}</div><div class="value">${euro.format(l.goods)}</div><div class="delta">${l.goodsRate?pct(l.goodsRate)+' vom Erlös':'noch keine Erlöse'}</div></article><article class="kpi db1"><div class="kpi-top"><span class="label">DB1 Live-Trend*</span>${infoButton('db1live')}</div><div class="value">${l.days?euro.format(l.liveDb1):'—'}</div><div class="delta">vorläufig – Abschluss verifiziert</div></article></div>
    <div class="section-head"><div><div class="eyebrow">FLOSIQ BRIDGE</div><h2>${f.connected?'Food-Waste-Daten laufen automatisch ein':'FLOSIQ verbinden'}</h2></div><span class="chip ${f.connected?'good':''}">${f.connected?'● LIVE':'nicht verbunden'}</span></div>
    ${f.connected?`<div class="flosiq-card"><div class="flosiq-head"><div><b>FLOSIQ · ${lm.label}</b><small>MetriQ liest den aktuellen Datenstand automatisch</small></div>${can('config.edit')?'<button class="ghost compact" data-disconnect-flosiq>Trennen</button>':''}</div><div class="flosiq-grid"><div><small>Food Loss</small><strong>${f.foodLoss!=null?Math.round(f.foodLoss)+' g':'—'}</strong><span>je Mittagessen</span></div><div><small>Nassmüll</small><strong>${f.waste.toFixed(1).replace('.',',')} kg</strong><span>gesamt</span></div><div><small>Überproduktion</small><strong>${f.cats.overproduction.toFixed(1).replace('.',',')} kg</strong><span>direkter Hebel</span></div><div><small>Food Rescue</small><strong>${fmt(f.rescues)}</strong><span>Rettungen</span></div></div></div>`:`<div class="notice"><div class="ico">♻️</div><div style="flex:1"><b>Essen + Food Waste nicht doppelt erfassen.</b><p>Wenn FLOSIQ auf demselben Gerät/Host läuft, kann MetriQ dessen Essenszahlen, Nassmüll, Food Loss, Überproduktion und Food-Rescue-Daten direkt lesen.</p>${can('config.edit')?'<button class="primary" data-connect-flosiq style="margin-top:9px">FLOSIQ automatisch verbinden →</button>':''}</div></div>`}
  </section>`;
}
function monthView(){if(!selectedRecord())return emptyArchiveView();return state.monthMode==='deep'?deepScanView():cockpitView()}
function emptyArchiveView(){return `<section class="screen">${monthNavigator()}<div class="eyebrow">MONATSABSCHLUSS</div><h1 class="title">Noch keine Daten für ${currentSite().name}.</h1><p class="subtitle">Jeder Betrieb bekommt seinen eigenen Datenraum. Lade den ersten Abschluss hoch, damit MetriQ die Historie aufbaut.</p>${can('upload')?'<button class="primary" data-start-upload>Deep Scan starten →</button>':''}</section>`}
function cockpitView(){const r=selectedRecord(),c=calc(r),inv=r.inventory||{items:[]},maxGoods=Math.max(1,...(r.suppliers||[]).map(s=>s.goods||0)),parts=(r.parts||[]).filter(p=>Math.abs(p.revenue)+Math.abs(p.result)+Math.abs(p.ware)>0);return`<section class="screen">${monthNavigator()}${monthTabs()}<div class="verified-hero"><div style="display:flex;justify-content:space-between;gap:12px"><div><div class="eyebrow">VERIFIZIERTER ABSCHLUSS</div><h1 style="font-size:31px;letter-spacing:-1px;margin:5px 0">${r.month}</h1><p class="subtitle" style="font-size:11px">${r.source} · ${r.audit.sheetCount} Blätter geprüft · Scan ${r.audit.version||'legacy'}</p></div><span class="chip ${r.audit.conflicts?'warn':'good'}">${r.audit.conflicts?'!':'✓'} ${r.audit.confidence??'—'}% Datenvertrauen</span></div><div class="hero-kpis"><div class="hero-kpi"><small>Nettoerlös</small><strong>${euro.format(c.revenue)}</strong></div><div class="hero-kpi"><small>Wareneinsatz</small><strong>${pct(c.warePct)}</strong></div><div class="hero-kpi"><small>Personal</small><strong>${pct(c.personalPct)}</strong></div><div class="hero-kpi"><small>DB1</small><strong>${pct(c.db1Pct)}</strong></div></div></div><div class="section-head"><div><div class="eyebrow">KERNKENNZAHLEN · ${r.month}</div><h2>Was du im Blick behalten musst</h2></div></div><div class="kpi-grid">${kpi('Wareneinsatzquote',pct(c.warePct),euro.format(c.ware),'ware','Verbrauch im Verhältnis zum Nettoerlös')}${kpi('Personalkostenquote',pct(c.personalPct),euro.format(c.personal),'personal','eigen + fremd im Abschluss')}${kpi('DB1',pct(c.db1Pct),euro.format(c.db1),'db1','aus der WISAG-Abschlusslogik','db1')}${kpi('Gesamtkostenquote',pct(c.totalCostPct),euro.format(c.totalCosts),'totalcost','alle Kosten vor DB1')}</div><div class="section-head"><div><div class="eyebrow">KOSTENFINGERABDRUCK · ${r.month}</div><h2>Was deinen Monat prägt</h2></div></div><div class="panel"><div class="cost-stage">${costColumn('Personal',c.personal,c.personalPct,'personal-bar',100)}${costColumn('Ware',c.ware,c.warePct,'ware-bar',Math.max(14,c.ware/Math.max(c.personal,c.ware)*100))}${costColumn('Sachkosten',c.sach,c.sachPct,'sach-bar',Math.max(14,c.sach/Math.max(c.personal,c.ware)*100))}</div></div><div class="section-head"><div><div class="eyebrow">KOSTENSTRUKTUR · ${r.month}</div><h2>So verteilt sich 1 € Nettoerlös</h2><p>Damit ist sofort sichtbar, welcher Anteil deines Erlöses in welche Kostenblöcke geht.</p></div>${infoButton('eurostruktur')}</div><div class="panel"><div class="euro-structure"><span style="width:${c.warePct}%;background:#8752ed"></span><span style="width:${c.personalPct}%;background:#39b9d2"></span><span style="width:${c.sachPct}%;background:#72c75f"></span><span style="flex:1;background:#ff7180"></span></div><div class="legend"><span><i style="background:#8752ed"></i>${c.warePct.toFixed(0)} ct Ware</span><span><i style="background:#39b9d2"></i>${c.personalPct.toFixed(0)} ct Personal</span><span><i style="background:#72c75f"></i>${c.sachPct.toFixed(0)} ct Sach</span><span><i style="background:#ff7180"></i>${c.db1Pct.toFixed(1).replace('.',',')} ct DB1</span></div></div><div class="section-head"><div><div class="eyebrow">TEILBETRIEBE · ${r.month}</div><h2>Welcher Bereich trägt das Ergebnis?</h2></div>${infoButton('teilbetriebe')}</div><div class="two-col">${parts.map(p=>`<div class="stat-card"><small>${p.name}</small><strong class="${p.result<0?'negative':'positive'}">${euro.format(p.result)}</strong><span>${euro.format(p.revenue)} Erlös · ${euro.format(p.ware)} Ware</span></div>`).join('')}</div><div class="section-head"><div><div class="eyebrow">KONFERENZSERVICE · ${r.month}</div><h2>Konferenzerlöse nach Kostenstelle</h2><p>Direkt aus Faktura HK – Abschlags- und Spitzabrechnungen werden ausgeschlossen.</p></div>${infoButton('konferenz')}</div>${conferenceRevenueBlock(r)}<div class="section-head"><div><div class="eyebrow">INVENTUR · ${r.month}</div><h2>Bestand und Veränderung</h2></div>${infoButton('inventur')}</div><div class="two-col"><div class="stat-card"><small>Inventur aktuell</small><strong>${euro.format(inv.totalCurrent)}</strong><span>${r.month}</span></div><div class="stat-card"><small>Vormonat</small><strong>${euro.format(inv.totalPrevious)}</strong><span class="${inv.delta<0?'negative':'positive'}">${inv.delta>=0?'+':''}${euro.format(inv.delta)} Veränderung</span></div></div><div class="inventory-list" style="margin-top:10px">${(inv.items||[]).map(x=>`<div class="row-card"><div class="left"><b>${x.name}</b><small>Vormonat ${euro.format(x.previous)}</small></div><div style="text-align:right"><strong>${euro.format(x.current)}</strong><small class="${x.delta<0?'negative':'positive'}">${x.delta>=0?'+':''}${euro.format(x.delta)}</small></div></div>`).join('')}</div><div class="section-head"><div><div class="eyebrow">WARENZUGANG · ${r.month}</div><h2>Nach Lieferant sortiert</h2><p>Bewusst Warenzugang – nicht Wareneinsatz. Die Inventur macht aus Einkäufen erst den tatsächlichen Verbrauch.</p></div>${infoButton('warenzugang')}</div><div class="supplier-list">${(r.suppliers||[]).filter(s=>s.goods>0).map(s=>`<button class="row-card" data-supplier="${esc(s.name)}" style="color:inherit;text-align:left"><div class="left" style="flex:1"><b>${s.name}</b><small>${state.supplierMap[s.name]||s.category||'Zuordnung fehlt'}</small><div class="supplier-bar"><span style="--w:${Math.max(3,s.goods/maxGoods*100)}%"></span></div></div><strong>${euro.format(s.goods)}</strong></button>`).join('')}</div><button class="ghost" data-open-supplier-map style="width:100%;margin-top:10px">Lieferanten-Zuordnung prüfen →</button></section>`}
function kpi(label,value,amount,info,note,cls=''){const n=parseFloat(String(value).replace(',','.'))||0;return`<article class="kpi ${cls}"><div class="kpi-top"><span class="label">${label}</span>${infoButton(info)}</div><div class="value counter" data-val="${n}" data-display="${value}">0</div><div class="delta">${amount} · ${note}</div></article>`}
function costColumn(name,val,p,cls,h){return`<div class="cost-col"><div class="cost-val">${euro.format(val)}</div><div class="bar-track"><div class="cost-bar ${cls}" style="--h:${Math.min(100,h)}%"></div></div><div class="cost-name">${name}</div><div class="cost-pct">${pct(p)}</div></div>`}
function conferenceRevenueBlock(r){
  const groups=conferenceGroups(r),total=conferenceTotal(r);
  if(!groups.length)return `<div class="panel"><div style="display:flex;justify-content:space-between;gap:12px;align-items:center"><div><b>Keine echten Konferenzbuchungen in ${r.month}</b><p class="subtitle" style="font-size:10px;margin-top:4px">Abschlagsrechnung und K+ Spitzabrechnung aus Faktura HK werden bewusst nicht als Konferenzerlös gezählt.</p></div><strong>${euro.format(0)}</strong></div></div>`;
  return `<div class="panel"><div style="display:flex;justify-content:space-between;gap:12px;align-items:flex-end;margin-bottom:12px"><div><div class="eyebrow">KONFERENZERLÖS GESAMT</div><h3 style="margin:4px 0 0">${euro.format(total)}</h3></div><span class="chip">${groups.length} Kostenstellen</span></div><div class="conference-list">${groups.map(g=>`<button class="row-card" data-conference="${esc(g.code||g.label)}" style="color:inherit;text-align:left"><div class="left"><b>${g.label}</b><small>${g.code?`Kostenstelle ${g.code} · `:''}${g.bookings} Buchung${g.bookings===1?'':'en'}</small></div><strong>${euro.format(g.revenue)}</strong></button>`).join('')}</div></div>`;
}
function deepScanView(){
  const r=selectedRecord(),c=calc(r),a=r.audit||{},checks=a.checks||[],coverage=a.coverage||[];
  return `<section class="screen">${monthNavigator()}${monthTabs()}<div class="eyebrow">DEEP SCAN · ${r.month}</div><h1 class="title">Warum dein Monat so aussieht.</h1><p class="subtitle">Nicht eine Zahl aus einer Seite – sondern eine Beweiskette aus mehreren Tabellenblättern. Kritische Widersprüche blockieren die Verifizierung.</p>
  <div class="trust-card"><div><div class="eyebrow">DATENVERTRAUEN · SCAN ${a.version||'legacy'}</div><strong>${a.confidence??'—'}%</strong><p>${a.conflicts||0} kritische Konflikte · ${a.warnings||0} Hinweise · ${a.sheetCount||0} Blätter gescannt</p></div><span class="trust-ring ${a.conflicts?'bad':'good'}">${a.conflicts?'!':'✓'}</span></div>
  <div class="section-head"><div><div class="eyebrow">01 · ERGEBNISBRÜCKE</div><h2>Vom Erlös zum DB1</h2></div>${infoButton('db1')}</div><div class="panel"><div class="two-col"><div class="stat-card"><small>Nettoerlös</small><strong>${euro.format(c.revenue)}</strong></div><div class="stat-card"><small>Gesamtkosten</small><strong>${euro.format(c.totalCosts)}</strong></div><div class="stat-card"><small>DB1</small><strong class="${c.db1>=0?'positive':'negative'}">${euro.format(c.db1)}</strong></div><div class="stat-card"><small>DB1-Quote</small><strong>${pct(c.db1Pct)}</strong></div></div></div>
  <div class="section-head"><div><div class="eyebrow">02 · BEWEISKETTE</div><h2>Welche Quellen bestätigen sich?</h2></div></div>
  ${checks.length?`<div class="proof-list">${checks.map(x=>`<div class="proof-row ${x.ok?'ok':'bad'}"><span class="proof-icon">${x.ok?'✓':'!'}</span><div><b>${x.label}</b><small>${x.detail||x.sources?.join(' ↔ ')||''}</small></div><em>${x.available===false?'Info':x.ok?'bestätigt':'Konflikt'}</em></div>`).join('')}</div>`:`<div class="notice"><div class="ico">↻</div><div><b>Dieser Abschluss wurde noch mit der alten Scan-Engine verifiziert.</b><p>Lade die Excel-Datei erneut hoch, damit V7 die mehrstufige Beweiskette erzeugt.</p></div></div>`}
  <div class="section-head"><div><div class="eyebrow">03 · BLATTABDECKUNG</div><h2>${a.sheetCount||0} Tabellenblätter wirklich durchlaufen</h2></div></div>
  ${coverage.length?`<details class="sheet-audit"><summary>Alle gescannten Blätter anzeigen <span>${coverage.length}</span></summary><div class="sheet-grid">${coverage.map(x=>`<div><b>${x.name}</b><small>${x.nonEmptyCells} belegte Zellen${x.month?' · '+x.month:''}${x.errors?' · '+x.errors+' Formelhinweise':''}</small></div>`).join('')}</div></details>`:`<div class="panel"><p class="subtitle" style="font-size:11px">Legacy-Scan: Blattdetails sind noch nicht gespeichert.</p></div>`}
  <div class="section-head"><div><div class="eyebrow">04 · BUCHUNGEN</div><h2>Was steckt hinter den Zahlen?</h2></div></div><div class="booking-list">${(r.transactions||[]).slice(0,14).map(t=>`<div class="row-card"><div class="left"><b>${t.supplier}</b><small>${t.remark||'REB'} · Waren ${euro.format(t.goods)}</small></div><strong>${euro.format(t.net)}</strong></div>`).join('')}</div></section>`
}
function hebelView(){
  const r=selectedRecord();if(!r)return emptyArchiveView();const c=calc(r),f=flosiqMonthData(liveMonthMeta().key),foreign=foreignPersonal(r),goods=supplierGoodsTotal(r),inv=r?.inventory?.totalCurrent||0,conf=conferenceTotal(r);
  const currentWaste=f.foodLoss??state.liveGoals.waste??70;
  return `<section class="screen">${monthNavigator()}<div class="eyebrow">WAS-WÄRE-WENN-LABOR</div><h1 class="title">Welche Hebel sind wirklich realistisch?</h1><p class="subtitle">MetriQ trennt Ergebnishebel, Umsatzchancen und Liquidität. Nichts wird schön gerechnet.</p>
    <div class="lever-priority"><div class="eyebrow">DEINE HEBEL FÜR ${r.month.toUpperCase()}</div><div class="lever-grid">
      ${leverIdea('01','Wareneinsatz','1 Prozentpunkt entspricht aktuell '+euro.format(c.revenue*.01)+' möglicher DB1-Wirkung.','hoch')}
      ${foreign>0?leverIdea('02','Fremdpersonal',euro.format(foreign)+' wurden im Abschluss erkannt – hier ist echte variable Kostenwirkung möglich.','mittel'):leverIdea('02','Personal','Festes Team: lieber Produktivität und Essenszahl verbessern statt Köpfe „wegzurechnen“.','struktur')}
      ${leverIdea('03','Einkauf & Lieferanten',euro.format(goods)+' Warenzugang ist Lieferanten zuordenbar. Schon kleine Konditionsverbesserungen wirken.','mittel')}
      ${leverIdea('04','Inventur / Bestand',euro.format(inv)+' Bestand bindet Liquidität. Bestandsabbau verbessert nicht automatisch den DB1, aber deinen Cash-Bedarf.','liquidität')}
      ${f.connected&&f.foodLoss!=null?leverIdea('05','Food Waste',Math.round(f.foodLoss)+' g/Essen aktuell aus FLOSIQ · Überproduktion '+f.cats.overproduction.toFixed(1).replace('.',',')+' kg.','hoch'):leverIdea('05','Food Waste','FLOSIQ verbinden, damit MetriQ den operativen Waste-Hebel mit der Warenquote zusammenführt.','daten')}
      ${leverIdea('06','Konferenzgeschäft',conf>0?euro.format(conf)+' Konferenzerlös erkannt. Zusätzliche Aufträge erhöhen den Umsatz – DB-Wirkung erst mit Kostenbasis bewerten.':'Noch kein echter Konferenzerlös in diesem Monat. Das ist eine Umsatzchance, aber kein erfundener DB-Hebel.','umsatz')}
    </div></div>

    <div class="section-head"><div><div class="eyebrow">1 · WARENEINSATZ</div><h2>Was bringt ein kleiner Schritt?</h2></div>${infoButton('ware')}</div>
    ${slider('wareSlider','Wareneinsatzquote',c.warePct,Math.max(25,c.warePct-8),c.warePct,.1,'%')}<div id="wareImpact" class="impact"></div>

    <div class="section-head"><div><div class="eyebrow">2 · EINKAUFSKONDITIONEN</div><h2>Nur auf echten Warenzugang</h2></div></div>
    ${slider('supplierSlider','Verbesserung auf Warenzugang',0,0,5,.1,'%')}<div id="supplierImpact" class="impact"></div>

    ${foreign>0?`<div class="section-head"><div><div class="eyebrow">3 · FREMDPERSONAL</div><h2>Variable Kosten statt Festgehälter</h2></div></div>${slider('foreignSlider','Reduktion Fremdpersonal',0,0,30,1,'%')}<div id="foreignImpact" class="impact"></div>`:''}

    <div class="section-head"><div><div class="eyebrow">4 · BESTAND</div><h2>Liquidität freisetzen</h2></div>${infoButton('inventur')}</div>
    ${slider('inventorySlider','Bestand reduzieren',0,0,25,1,'%')}<div id="inventoryImpact" class="impact"></div>

    <div class="section-head"><div><div class="eyebrow">5 · FOOD WASTE</div><h2>Operativ besser werden</h2></div></div>
    ${f.connected&&f.foodLoss!=null?`${slider('wasteSlider','Food Loss',f.foodLoss,Math.max(20,f.foodLoss-100),f.foodLoss,1,' g')}<div id="wasteImpact" class="impact"></div>`:`<div class="notice"><div class="ico">♻️</div><div><b>Dieser Hebel wird mit FLOSIQ stark.</b><p>Dann kennt MetriQ Food Loss, Überproduktion und Essenszahlen automatisch – und muss nichts schätzen.</p><button class="primary" data-connect-flosiq style="margin-top:8px">FLOSIQ verbinden</button></div></div>`}
  </section>`;
}
function leverIdea(n,title,copy,tag){return `<div class="lever-card"><span class="lever-no">${n}</span><div><div class="lever-title"><b>${title}</b><em>${tag}</em></div><p>${copy}</p></div></div>`}
function slider(id,title,val,min,max,step,suffix){return`<div class="slider-card"><div class="slider-top"><h3>${title}</h3><b id="${id}Value">${Number(val).toFixed(step<1?1:0).replace('.',',')}${suffix}</b></div><input id="${id}" type="range" min="${min}" max="${max}" value="${val}" step="${step}"></div>`}
function analysisView(){if(state.analysisDetail)return analysisDetailView();const records=periodRecords();return`<section class="screen"><div class="eyebrow">ANALYSEN</div><h1 class="title">Dein Betrieb im Verlauf.</h1><p class="subtitle">Finger auf die Kurve legen, nach links und rechts fahren und den Monatswert live sehen – nur mit tatsächlich hochgeladenen Abschlüssen.</p><div class="period-bar"><span class="chip">${state.archives.length} Monate vorhanden</span><button class="period-pill" data-open-period>${periodText()} ▾</button></div>${analysisCard('revenue','Nettoerlös',records)}${analysisCard('warePct','Wareneinsatzquote',records)}${analysisCard('db1','DB1',records)}${analysisCard('inventory','Inventurbestand',records)}${analysisCard('meals','Essenszahlen',records)}${analysisCard('conference','Konferenzerlöse',records)}${state.flosiq.enabled?flosiqAnalysisCard():''}</section>`}
function periodText(){return state.analysisPeriod==='all'?'Alle Monate':`${state.analysisPeriod} Monate`}
function periodRecords(){const all=sortedArchives();return state.analysisPeriod==='all'?all:all.slice(-Number(state.analysisPeriod||12))}
function metricVal(r,key){const c=calc(r);if(key==='revenue')return c.revenue;if(key==='warePct')return c.warePct;if(key==='db1')return c.db1;if(key==='inventory')return r.inventory?.totalCurrent||0;if(key==='meals')return r.metrics?.meals||0;if(key==='conference')return conferenceTotal(r);return 0}
function metricFormat(key,v){if(key==='warePct')return pct(v);if(key==='meals')return fmt(v);return euro.format(v)}
function analysisCard(key,title,records){const current=records.at(-1),value=current?metricVal(current,key):0,id=`chart_${key}`;return`<div class="analysis-card"><div class="analysis-card-head"><div><h3>${title}</h3><span class="subtitle" style="font-size:10px">${current?.month||'Noch keine Daten'}</span></div><div class="big">${metricFormat(key,value)}</div></div>${interactiveChart(id,key,records)}<div class="analysis-link"><button data-analysis="${key}">Zur Analyse ›</button></div></div>`}
function interactiveChart(id,key,records){chartRegistry[id]={key,records};if(!records.length)return`<div class="chart-wrap"></div>`;const vals=records.map(r=>metricVal(r,key)),min=Math.min(...vals),max=Math.max(...vals),w=600,h=145,p=12,point=(v,i)=>{const x=records.length===1?w/2:p+i*(w-2*p)/(records.length-1),y=h-p-(v-min)/(max-min||1)*(h-2*p);return[x,y]},pts=vals.map(point),poly=pts.map(a=>a.join(',')).join(' '),area=`${p},${h-p} ${poly} ${records.length===1?w/2:w-p},${h-p}`;return`<div class="chart-wrap interactive-chart" data-chart="${id}"><svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><line class="gridline" x1="0" y1="36" x2="600" y2="36"/><line class="gridline" x1="0" y1="72" x2="600" y2="72"/><line class="gridline" x1="0" y1="108" x2="600" y2="108"/><polygon class="chart-area" points="${area}"/><polyline class="chart-line" points="${poly}"/>${pts.map(([x,y])=>`<circle class="chart-dot" cx="${x}" cy="${y}" r="4"/>`).join('')}<line class="chart-cross" x1="0" y1="5" x2="0" y2="${h-5}"/><circle class="chart-focus" cx="0" cy="0" r="6"/></svg><div class="chart-tooltip"></div></div><div class="chart-months">${records.map(r=>`<span>${monthShort(r.key)}</span>`).join('')}</div>`}
function analysisDetailView(){const key=state.analysisDetail,records=periodRecords(),selected=records.find(r=>r.key===state.analysisPointKey)||records.at(-1),v=selected?metricVal(selected,key):0,title={revenue:'Nettoerlös',warePct:'Wareneinsatzquote',db1:'DB1',inventory:'Inventurbestand',meals:'Essenszahlen',conference:'Konferenzerlöse'}[key]||key,bookings=metricBookings(selected,key);return`<section class="screen"><button class="detail-back" data-analysis-back>‹ Zurück zu Analysen</button><div class="eyebrow">ANALYSE</div><h1 class="title">${title}</h1><div class="period-bar"><span class="chip">${selected?.month||'—'}</span><button class="period-pill" data-open-period>${periodText()} ▾</button></div><div class="detail-value"><strong>${metricFormat(key,v)}</strong><span>Finger auf die Kurve legen und bewegen</span></div>${interactiveChart('detailChart',key,records)}<div class="section-head"><div><div class="eyebrow">MONATE</div><h2>Hochgeladene Abschlüsse</h2></div></div><div class="month-list">${records.slice().reverse().map(r=>`<button class="row-card" data-analysis-month="${r.key}" style="color:inherit;text-align:left"><div class="left"><b>${r.month}</b><small>${r.audit.sheetCount} Blätter · ${r.audit.conflicts} Konflikte</small></div><strong>${metricFormat(key,metricVal(r,key))}</strong></button>`).join('')}</div><div class="section-head"><div><div class="eyebrow">BUCHUNGEN · ${selected?.month||''}</div><h2>${bookingTitle(key)}</h2></div></div>${bookings.length?`<div class="booking-list">${bookings.map(b=>`<div class="row-card"><div class="left"><b>${b.title}</b><small>${b.sub||''}</small></div><strong>${b.value}</strong></div>`).join('')}</div>`:`<div class="panel"><p class="subtitle" style="font-size:11px">Für diese Kennzahl gibt es keine einzelnen Buchungen.</p></div>`}</section>`}
function bookingTitle(key){return key==='warePct'?'Warenbuchungen nach Lieferant':key==='revenue'?'Erlösbuchungen':key==='conference'?'Konferenzbuchungen aus Faktura HK':key==='db1'?'Bausteine des DB1':key==='inventory'?'Inventurpositionen':'Tages-/Menüdaten'}
function metricBookings(r,key){if(!r)return[];if(key==='warePct')return(r.transactions||[]).filter(t=>t.goods>0).map(t=>({title:t.supplier,sub:t.remark,value:euro.format(t.goods)}));if(key==='revenue')return(r.revenueBookings||[]).map(t=>({title:t.service||t.customer||t.type,sub:t.costCenter,value:euro.format(t.net)}));if(key==='conference')return conferenceRows(r).map(t=>({title:t.customer||t.costCenter||t.service,sub:`Faktura HK · ${t.service||''}`,value:euro.format(t.net)}));if(key==='inventory')return(r.inventory?.items||[]).map(x=>({title:x.name,sub:`Vormonat ${euro.format(x.previous)}`,value:euro.format(x.current)}));if(key==='meals')return(r.dailyMeals||[]).map(x=>({title:`Tag ${x.day}`,sub:'Speisenverteilung',value:`${fmt(x.meals)} Essen`}));if(key==='db1'){const c=calc(r);return[{title:'Nettoerlös',sub:'Ausgangspunkt',value:euro.format(c.revenue)},{title:'Gesamtkosten',sub:'werden abgezogen',value:'− '+euro.format(c.totalCosts)},{title:'DB1',sub:'verifizierter Rest',value:euro.format(c.db1)}]}return[]}

function flosiqHistory(){
  const raw=flosiqRaw(),keys=[...new Set([...raw.entries.map(x=>String(x.date||'').slice(0,7)),...raw.meals.map(x=>String(x.date||'').slice(0,7))].filter(x=>/^\d{4}-\d{2}$/.test(x)))].sort();
  return keys.map(key=>({key,month:monthLabel(key),value:flosiqMonthData(key).foodLoss}));
}
function flosiqAnalysisCard(){
  const hist=flosiqHistory().filter(x=>x.value!=null),last=hist.at(-1);
  if(!hist.length)return `<div class="analysis-card"><div class="analysis-card-head"><div><h3>Food Loss · FLOSIQ</h3><span class="subtitle" style="font-size:10px">Noch keine vollständigen FLOSIQ-Monate</span></div></div></div>`;
  const records=hist.map(x=>({key:x.key,month:x.month,metrics:{flosiq:x.value}}));
  chartRegistry['chart_flosiq']={key:'flosiq',records};
  return `<div class="analysis-card"><div class="analysis-card-head"><div><h3>Food Loss · FLOSIQ</h3><span class="subtitle" style="font-size:10px">${last.month}</span></div><div class="big">${Math.round(last.value)} g</div></div>${interactiveFlosiqChart('chart_flosiq',records)}<div class="analysis-link"><button data-info="flosiq">FLOSIQ-Daten ›</button></div></div>`;
}
function interactiveFlosiqChart(id,records){
  const vals=records.map(r=>r.metrics.flosiq),min=Math.min(...vals),max=Math.max(...vals),w=600,h=145,p=12;
  const point=(v,i)=>{const x=records.length===1?w/2:p+i*(w-2*p)/(records.length-1),y=h-p-(v-min)/(max-min||1)*(h-2*p);return[x,y]};
  const pts=vals.map(point),poly=pts.map(a=>a.join(',')).join(' ');
  return `<div class="chart-wrap flosiq-chart"><svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><line class="gridline" x1="0" y1="36" x2="600" y2="36"/><line class="gridline" x1="0" y1="72" x2="600" y2="72"/><line class="gridline" x1="0" y1="108" x2="600" y2="108"/><polyline class="flosiq-line" points="${poly}"/>${pts.map(([x,y])=>`<circle class="flosiq-dot" cx="${x}" cy="${y}" r="4"/>`).join('')}</svg></div><div class="chart-months">${records.map(r=>`<span>${monthShort(r.key)}</span>`).join('')}</div>`;
}

function median(vals){const a=vals.map(Number).filter(Number.isFinite).sort((x,y)=>x-y);if(!a.length)return null;const m=Math.floor(a.length/2);return a.length%2?a[m]:(a[m-1]+a[m])/2}
function benchmarkLatestPerSite(){const map=new Map();for(const r of state.benchmarks?.records||[]){const prev=map.get(r.siteToken);if(!prev||String(r.monthKey||'')>String(prev.monthKey||''))map.set(r.siteToken,r)}return [...map.values()]}
function benchmarkCohort(){const site=currentSite(),cur=selectedRecord(),meals=+cur?.metrics?.meals||0;return benchmarkLatestPerSite().filter(x=>{if(state.benchmarks?.siteToken&&x.siteToken===state.benchmarks.siteToken)return false;const sameContract=!site.contract||!x.contract||norm(site.contract)===norm(x.contract);const mealFit=!meals||!x.meals||(+x.meals>=meals*.5&&+x.meals<=meals*1.5);return sameContract&&mealFit})}
function benchmarkSummary(){const c=benchmarkCohort();return{sites:c.length,warePct:median(c.map(x=>x.warePct)),personalPct:median(c.map(x=>x.personalPct)),sachPct:median(c.map(x=>x.sachPct)),db1Pct:median(c.map(x=>x.db1Pct)),meals:median(c.map(x=>x.meals))}}
function downloadJson(obj,name){const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}
async function anonymousSiteToken(){if(state.benchmarks?.siteToken)return state.benchmarks.siteToken;const token=(crypto.randomUUID?.()||[...crypto.getRandomValues(new Uint8Array(16))].map(x=>x.toString(16).padStart(2,'0')).join('')).replace(/-/g,'').slice(0,24);state.benchmarks.siteToken=token;saveState();return token}
async function exportBenchmarkBundle(){if(!can('backup'))return toast('Keine Berechtigung');const token=await anonymousSiteToken(),site=currentSite(),records=sortedArchives().filter(x=>x.verified&&!x.audit?.conflicts).map(r=>{const c=calc(r);return{siteToken:token,monthKey:r.key,contract:site.contract||r.model||'',employees:+site.employees||0,seats:+site.seats||0,meals:+r.metrics?.meals||0,revenue:c.revenue,warePct:c.warePct,personalPct:c.personalPct,sachPct:c.sachPct,db1Pct:c.db1Pct}});if(!records.length)return toast('Noch keine verifizierten Monate');downloadJson({schema:'metriq-benchmark-v1',exportedAt:new Date().toISOString(),privacy:'anonymized-kpi-only',records},`metriq-benchmark-${token}-${new Date().toISOString().slice(0,10)}.json`);addAudit('benchmark.exported',`${records.length} anonymisierte Monate`);saveState();render();toast('Benchmark-Paket anonymisiert exportiert')}
function openBenchmarkImportModal(){if(!can('backup'))return toast('Keine Berechtigung');openModal(`<h2>Benchmark-Daten importieren</h2><p class="help-copy">Importiert nur anonymisierte KPI-Pakete aus anderen MetriQ-Pilotbetrieben. Keine Lieferanten, Personen, Kunden oder Einzelbuchungen.</p><div class="field"><label>MetriQ Benchmark JSON</label><input id="benchmarkFile" type="file" accept="application/json,.json"></div><button id="benchmarkImportBtn" class="primary" style="width:100%;margin-top:14px">Anonymisierte Daten prüfen & importieren</button>`);$('#benchmarkImportBtn').onclick=()=>{const f=$('#benchmarkFile').files?.[0];if(!f)return toast('Bitte Datei auswählen');importBenchmarkBundle(f)}}
async function importBenchmarkBundle(file){try{const obj=JSON.parse(await file.text());if(obj?.schema!=='metriq-benchmark-v1'||!Array.isArray(obj.records))throw new Error('Kein gültiges Benchmark-Paket');const clean=obj.records.filter(x=>x?.siteToken&&/^\d{4}-\d{2}$/.test(x.monthKey||'')).map(x=>({siteToken:String(x.siteToken).slice(0,40),monthKey:x.monthKey,contract:String(x.contract||''),employees:+x.employees||0,seats:+x.seats||0,meals:+x.meals||0,revenue:+x.revenue||0,warePct:+x.warePct||0,personalPct:+x.personalPct||0,sachPct:+x.sachPct||0,db1Pct:+x.db1Pct||0,importedAt:new Date().toISOString()}));if(!clean.length)throw new Error('Keine verwertbaren Datensätze');const map=new Map((state.benchmarks.records||[]).map(x=>[`${x.siteToken}|${x.monthKey}`,x]));for(const x of clean)map.set(`${x.siteToken}|${x.monthKey}`,x);state.benchmarks.records=[...map.values()];addAudit('benchmark.imported',`${clean.length} anonymisierte Monate aus ${new Set(clean.map(x=>x.siteToken)).size} Betrieb(en)`);saveState();closeModal();render();toast('Benchmark-Daten importiert')}catch(e){toast(e.message||'Benchmark-Import fehlgeschlagen')}}
function startPilot(){if(!state.pilot.startedAt){state.pilot.startedAt=new Date().toISOString();addAudit('pilot.started','Pilotnachweis gestartet');saveState();render();toast('Pilotnachweis gestartet')}else toast('Pilot läuft bereits')}
function openPilotNoteModal(){openModal(`<h2>Pilot-Ergebnis festhalten</h2><p class="help-copy">Damit wir später nicht nur sagen „fühlt sich gut an“, sondern Wirkung belegen können.</p><div class="field"><label>Beobachtung / Feedback</label><textarea id="pilotNote" rows="4" placeholder="z. B. Monatsabschluss in 12 statt 35 Minuten verstanden"></textarea></div><div class="form-grid"><div class="field"><label>Zeit gespart (Min.)</label><input id="pilotMinutes" type="number" min="0" step="1"></div><div class="field"><label>Nutzwert 1–5</label><select id="pilotScore"><option value="">—</option><option>1</option><option>2</option><option>3</option><option>4</option><option>5</option></select></div></div><button id="savePilotNote" class="primary" style="width:100%;margin-top:14px">Pilotbeleg speichern</button>`);$('#savePilotNote').onclick=()=>{const note=$('#pilotNote').value.trim(),minutes=Math.max(0,+$('#pilotMinutes').value||0),score=+$('#pilotScore').value||null;if(!note&&!minutes&&!score)return toast('Bitte mindestens einen Wert eintragen');state.pilot.notes=Array.isArray(state.pilot.notes)?state.pilot.notes:[];state.pilot.notes.unshift({at:new Date().toISOString(),siteId:state.workspace.siteId,note,minutes,score});state.pilot.notes=state.pilot.notes.slice(0,200);addAudit('pilot.evidence.added',`${minutes} Min. · Score ${score||'—'}`);saveState();closeModal();render();toast('Pilotbeleg gespeichert')}}

