function baseBackupPayload(){return{schema:'metriq-backup-v7',appVersion:APP_VERSION,exportedAt:new Date().toISOString(),state}}
function exportBackup(){if(!can('backup'))return toast('Keine Berechtigung');openModal(`<h2>Sicheres MetriQ-Backup</h2><p class="help-copy">Empfohlen: Passwort setzen. Dann wird der komplette Datenbestand vor dem Download mit AES-GCM verschlüsselt.</p><div class="field"><label>Backup-Passwort</label><input id="backupPassword" type="password" autocomplete="new-password" placeholder="mindestens 8 Zeichen"></div><button id="secureBackupBtn" class="primary" style="width:100%;margin-top:10px">🔒 Verschlüsselt exportieren</button><button id="plainBackupBtn" class="ghost" style="width:100%;margin-top:10px">Nur lokal · unverschlüsselt exportieren</button>`);$('#secureBackupBtn').onclick=async()=>{const password=$('#backupPassword').value;if(password.length<8)return toast('Mindestens 8 Zeichen');try{const envelope=await secureBackupEnvelope(baseBackupPayload(),password);downloadJson(envelope,`metriq-backup-secure-${state.workspace.siteId}-${new Date().toISOString().slice(0,10)}.json`);addAudit('data.backup.exported','AES-GCM verschlüsseltes Backup');saveState();closeModal();render();toast('Verschlüsseltes Backup exportiert')}catch(e){toast('Verschlüsselung fehlgeschlagen')}};$('#plainBackupBtn').onclick=()=>{downloadJson(baseBackupPayload(),`metriq-backup-${state.workspace.siteId}-${new Date().toISOString().slice(0,10)}.json`);addAudit('data.backup.exported','Unverschlüsseltes lokales Backup');saveState();closeModal();render();toast('Lokales Backup exportiert')}}
