function applyBackupPayload(obj,fileName){if(obj?.schema!=='metriq-backup-v7'||!obj.state)throw new Error('Kein gültiges MetriQ V7 Backup');state=obj.state;state.workspace={...defaultState.workspace,...state.workspace};state.sites=Array.isArray(state.sites)&&state.sites.length?state.sites:clone(defaultState.sites);state.auditLog=Array.isArray(state.auditLog)?state.auditLog:[];state.benchmarks={...defaultState.benchmarks,...(state.benchmarks||{})};state.pilot={...defaultState.pilot,...(state.pilot||{})};addAudit('data.backup.imported',fileName);saveState();closeModal();applyTheme();render();toast('Backup wiederhergestellt')}
async function importBackup(file){try{const obj=JSON.parse(await file.text());if(obj?.schema==='metriq-secure-backup-v1'){openModal(`<h2>Verschlüsseltes Backup</h2><p class="help-copy">Gib das Passwort ein, mit dem dieses Backup erstellt wurde.</p><div class="field"><label>Backup-Passwort</label><input id="restorePassword" type="password" autocomplete="current-password"></div><button id="unlockBackup" class="primary" style="width:100%;margin-top:14px">Entschlüsseln & wiederherstellen</button>`);$('#unlockBackup').onclick=async()=>{try{const plain=await openSecureBackup(obj,$('#restorePassword').value);applyBackupPayload(plain,file.name)}catch(e){toast('Passwort falsch oder Backup beschädigt')}};return}applyBackupPayload(obj,file.name)}catch(e){toast(e.message||'Backup ungültig')}}
